import React from 'react';
import { Routes, Route } from 'react-router-dom';
import './App.css';

// Import your components
import Login from './components/Auth/login';
import Register from './components/Auth/register';
import FirstLogin from './components/Auth/firstLogin';
import Logout from './components/Auth/logout';
import ProtectedRoute from './components/Auth/ProtectedRoute';

// Import your pages
import NovoProcedimento from './pages/novoProcedimento';
import NovoProcesso from './pages/novoProcesso';
import TableDisplay from './pages/tableDisplay';
import SelectPdf from './pages/selectPdf';
import Loading from './pages/loading';

function App() {
  return (
    <div className="App">
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/first-login" element={<FirstLogin />} />
        <Route path="/logout" element={<Logout />} />
        <Route path="/loading" element={<Loading />} />
        
        {/* Protected Routes */}
        <Route path="/" element={<ProtectedRoute><TableDisplay /></ProtectedRoute>} />
        <Route path="/novo-procedimento" element={<ProtectedRoute><NovoProcedimento /></ProtectedRoute>} />
        <Route path="/novo-processo" element={<ProtectedRoute><NovoProcesso /></ProtectedRoute>} />
        <Route path="/select-pdf" element={<ProtectedRoute><SelectPdf /></ProtectedRoute>} />
      </Routes>
    </div>
  );
}

export default App;
